function removeUnwantedCharacters(htmlString) {
                // 이모지 및 제어 문자, 특정 특수 문자 제거를 위한 정규식
                const emojiAndControlCharsRegex =
                /[\p{Emoji}\u200D\u0000-\u001F\u007F-\u009F\u200B-\u200D\uFEFF]/gu;
                const unwantedCharsRegex = /[*■]/g; // * 및 ■ 문자

                // HTML 문자열에서 이모지, 제어 문자, 특정 특수 문자 제거
                return htmlString
                .replace(emojiAndControlCharsRegex, '') // 이모지 및 제어 문자 제거
                .replace(unwantedCharsRegex, ''); // * 및 ■ 문자 제거
                }

